'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const m = nextInt();
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < m; i++) {
  const a = nextInt() - 1;
  const b = nextInt() - 1;
  graph[a].push(b);
  graph[b].push(a);
}

const visited = new Uint8Array(n);
const marked = new Uint8Array(n);
const stack = [];
let answer = '-1';

for (let start = 0; start < n && answer === '-1'; start++) {
  if (visited[start]) continue;

  const component = [];
  visited[start] = 1;
  stack.push(start);

  while (stack.length > 0) {
    const v = stack.pop();
    component.push(v);
    for (const u of graph[v]) {
      if (!visited[u]) {
        visited[u] = 1;
        stack.push(u);
      }
    }
  }

  const size = component.length;
  let candidate = -1;
  for (const v of component) {
    if (graph[v].length < size - 1) {
      candidate = v;
      break;
    }
  }

  if (candidate !== -1) {
    for (const u of graph[candidate]) marked[u] = 1;
    for (const v of component) {
      if (v !== candidate && !marked[v]) {
        answer = `${candidate + 1} ${v + 1}`;
        break;
      }
    }
  }
}

